// Contrasts config-only Connect movement with a hand-written consumer that needs custom logic.
package com.bank.integration.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class ConnectVsCustomDemo {

    private static final Logger log = Logger.getLogger("Integration");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<Txn> table = List.of(
            new Txn(1, "SAV2001", new BigDecimal("20000")),
            new Txn(2, "CUR3001", new BigDecimal("750000"))
        );

        log.info("=== KAFKA CONNECT style: config only, no business logic ===");
        ConnectPipeline connect = new ConnectPipeline();
        connect.run(table);   // source → topic → sink, offsets + scaling handled by runtime

        log.info("=== CUSTOM CONSUMER style: needed for per-record enrichment + branching ===");
        FraudEnrichingConsumer custom = new FraudEnrichingConsumer(new BigDecimal("500000"));
        for (Txn t : table) custom.onRecord(t);
    }
}

// ─── Would be in Txn.java ───
class Txn {
    final long id; final String accountId; final BigDecimal amount;
    Txn(long id, String accountId, BigDecimal amount) {
        this.id = id; this.accountId = accountId; this.amount = amount;
    }
}

// ─── Would be in ConnectPipeline.java (models Connect runtime — no business code) ───
class ConnectPipeline {
    private static final Logger log = Logger.getLogger("Integration");
    void run(List<Txn> table) {
        List<String> topic = new ArrayList<>();
        // Source connector: pure copy, offset + scaling + fault tolerance by runtime.
        for (Txn t : table) {
            topic.add("{\"id\":" + t.id + ",\"account\":\"" + t.accountId
                    + "\",\"amount\":" + t.amount + "}");
            log.info(() -> "connect-source imported id=" + t.id + " (runtime tracks offset)");
        }
        // Sink connector: pure copy out to storage, offsets committed by runtime.
        log.info(() -> "connect-sink archived " + topic.size() + " records to S3 (no code)");
    }
}

// ─── Would be in FraudEnrichingConsumer.java (hand-written: bespoke logic) ───
class FraudEnrichingConsumer {
    private static final Logger log = Logger.getLogger("Integration");
    private final BigDecimal threshold;
    FraudEnrichingConsumer(BigDecimal threshold) { this.threshold = threshold; }

    // Custom logic no connector can do: live scoring + conditional branching.
    void onRecord(Txn t) {
        int score = scoreWithInternalService(t);     // enrichment
        if (t.amount.compareTo(threshold) > 0 || score > 80) {
            log.warning(() -> "custom: HOLD txn id=" + t.id + " account=" + t.accountId
                    + " amount=Rs." + t.amount + " score=" + score);
        } else {
            log.info(() -> "custom: PASS txn id=" + t.id + " account=" + t.accountId
                    + " score=" + score);
        }
    }
    private int scoreWithInternalService(Txn t) {
        // pretend call to a fraud model; big amounts score higher
        return t.amount.compareTo(new BigDecimal("500000")) > 0 ? 90 : 10;
    }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
